from pathlib import Path
import csv,json
P=Path(__file__).resolve().parent
rows=[]
def claim(id,t,s,source='',locator='',quote='',basis='',scope=''):
 rows.append(dict(id=id,type=t,status='active',statement=s,source=source,locator=locator,quote=quote,basis=basis,scope=scope))
def fact(id,s,source,loc,quote=None):
 records=[json.loads(l) for l in (P/'evidence'/f'{source}.jsonl').read_text().splitlines()]
 text=next(x['text'] for x in records if x['locator']==loc)
 claim(id,'fact',s,source,loc,quote or text,scope='Только разрешённый источник указанной версии; синтетический продукт, кроме снимков справки.')
fact('C-001','Быстрое выполнение шаблона может не создавать события task_created; переход из напоминания не означает выполнение.','S-001@1','line:5','Быстрое выполнение из шаблона может сразу записать выполнение без отдельного события создания.')
fact('C-002','Определение legacy_setup_flag утрачено; еженедельная задача может сдвигать день полезного действия.','S-001@1','line:7')
fact('C-003','Даты календарные UTC, недели регистрации начинаются в понедельник.','S-001@1','line:11')
fact('C-004','Покрытие относится к платформе и дню событий; partial означает возможные потери, даты за календарём не выгружены.','S-001@1','line:15')
fact('C-005','Нет фактов отправки, доставки и показа уведомлений, а справка конкурентов не доказывает удержание Ритма.','S-001@1','line:17')
fact('C-006','Реестр содержит платформу, канал, цель и legacy_setup_flag.','S-002@1','line:1')
fact('C-007','Календарь фиксирует частичное покрытие Android 22 июля.','S-004@1','line:104')
for i in range(8,13):fact(f'C-{i:03d}',f'Часть {i-7} событий имеет поля идентификаторов, даты и типа события.',f'S-{i:03d}@1','line:1')
fact('C-013','Снимок Google Tasks описывает создание, изменение и удаление повторяющихся задач.','S-005@1','Manage repeating tasks in Google Tasks & Google Calendar / introduction (Android)')
fact('C-014','Снимок Microsoft To Do описывает выбор времени напоминания.','S-006@1','Add a reminder in Microsoft To Do / step 2')
fact('C-015','Снимок Todoist описывает повторяющуюся дату естественным языком в названии задачи.','S-007@1','Add a recurring date in the task name / web instructions')
b='C-003,C-004,C-006,C-007,C-008,C-009,C-010,C-011,C-012'
scope='Расчёт analyze.py и summarize.py, analysis-results.json и analysis.md; все строки S-002@1, S-004@1, S-008@1—S-012@1 (соответствие оригиналу S-003@1 в split-map.json). Только синтетические аккаунты. Единица user_id; дедупликация event_id; отсутствующее событие считается нулём лишь при complete в целевом окне. Это вычисленный вывод из полных таблиц, не факт из одной процитированной строки.'
claim('C-016','inference','3020 уникальных регистраций; 85080 сообщений, 83738 уникальных event_id; 1342 точных повтора, нет конфликтов ID, сирот и событий до регистрации. Пропуски: канал 155, цель 404, legacy 246.',basis=b,scope=scope)
claim('C-017','inference','Полезный D7 (создание ИЛИ выполнение) в полных когортах 28.47–35.64%; первая 74/242=30.58%, последняя полная 104/356=29.21%. Разность −1.37 п.п., приближённый 95% интервал [−8.85;6.12] п.п.; устойчивый обвал не установлен.',basis=b,scope=scope+' Интервал пересчитать по analysis.md; не доказательство отсутствия снижения.')
claim('C-018','inference','D30 в полных когортах: 56/242,56/275,71/259,47/318,65/288; не монотонен. С 20 июля полных индивидуальных D30 нет; 13 июля только 40 из 340 наблюдаемы. Когорту 22 июня и Android с неполным покрытием не смешивать с полными.',basis=b,scope=scope)
claim('C-019','inference','При весах каналов первой когорты D7 первой/последней полных когорт составляет 30.58%/30.56%, против сырых 30.58%/29.21%; paid_social вырос с 59/242 до 145/356. Это согласуется с вкладом состава, но не устанавливает причинную долю.',basis=b,scope=scope+' Неизвестный канал отдельная страта; последняя метка не рандомизация, малые страты и остаточное смешение.')
claim('C-020','inference','Метрика чувствительна к событию и окну: первая когорта D7 выполнение 69/242=28.51%, полезное действие 30.58%, foreground 45.87%, любое событие 47.93%; W7=218/242=90.08%, W30=195/242=80.58%. Фоновую синхронизацию нельзя выдавать за полезный возврат.',basis='C-001,'+b,scope=scope+' Foreground включает app_open/task_created/task_completed/reminder_opened. W7=D7–13, W30=D28–34; не точечный D7/D30.')
claim('C-021','inference','208 аккаунтов меняют классификацию ранней активации при добавлении task_completed к task_created. В полном D7-пуле раннее полезное действие: 572/1661=34.44% против 123/598=20.57%; legacy=1:331/984=33.64%, legacy=0:301/1088=27.67%.',basis='C-001,C-002,'+b,scope=scope+' Активация D0–D1; complete обоих дней; ассоциация, мотивация и канал могут смешивать эффект. Legacy не определение пользы.')
claim('C-022','inference','В полном D7-пуле с полными D0–D1 раннее включение напоминаний связано с D7 275/661=41.60% против 420/1598=26.28%; для D30 113/412=27.43% против 182/970=18.76%. Это не эффект отправки и не оценка CTR.',basis='C-005,'+b,scope=scope+' Самоотбор; неизвестны экспозиция и доставка; настройка не равна отправке. Не сравнивать ever-enabled с удержанием без временного окна.')
claim('C-023','hypothesis','Короткий путь к первой подходящей задаче и добровольному повтору повысит полезные возвращения без роста давления уведомлений.',basis='C-001,C-002,C-021',scope='Проверять рандомизированным тестом; исходные наблюдения синтетические, функция повтора уже существует, спрос не подтверждён.')
claim('C-024','hypothesis','Контекстное предложение выбрать время напоминания может помочь возвращению, но усиление массовых push может увеличить раздражение.',basis='C-005,C-022,C-014',scope='Нужны согласие и измерение доставки/отключений; знак эффекта и спрос пока неизвестны.')
claim('C-025','inference','Предпочтителен ограниченный тест упрощённого первого полезного действия; массовое усиление push и закрытие сервиса не обоснованы этими данными.',basis='C-017,C-018,C-019,C-020,C-021,C-022,C-023,C-024',scope='Нормативная рекомендация при неизвестных затратах и выручке; запуск требует выбора руководителя, проверки живой телеметрии и ресурсной сметы.')
# Synthetic source observations are hypothesis anchors under the project claim model.
for row in rows:
 if row['source'] and row['source'] not in ['S-001@1','S-005@1','S-006@1','S-007@1']:
  row['type']='hypothesis'
  row['scope']='Синтетическая опора для расчёта, не свидетельство спроса. '+row['source']+' / '+row['locator']+' / дословно: '+row['quote']
  row['source']=row['locator']=row['quote']=''
with (P/'claims.tsv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=['id','type','status','statement','source','locator','quote','basis','scope'],delimiter='\t',lineterminator='\n');w.writeheader();w.writerows(rows)
